<?php
require_once __DIR__ . '/_layout.php';
$users = db()->query('SELECT user_id AS id, full_name, email, contact_number, account_status, created_at FROM users ORDER BY created_at DESC')->fetchAll();
admin_header('Manage users');
?>
<section class="surface-card"><p class="help-text">Passwords are never displayed. Accounts are only included when registered or provisioned in the users table.</p><div class="admin-table-wrap"><table class="table table-hover align-middle"><thead><tr><th>User</th><th>Email</th><th>Contact</th><th>Joined</th><th>Account status</th><th>Actions</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['full_name']) ?></td><td><?= e($user['email']) ?></td><td><?= e($user['contact_number']) ?></td><td><?= e(date('M j, Y', strtotime($user['created_at']))) ?></td><td><?= e($user['account_status']) ?></td><td class="text-nowrap"><form class="d-inline" method="post" action="../actions/admin.php"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?= (int) $user['id'] ?>"><input type="hidden" name="status" value="<?= $user['account_status'] === 'Active' ? 'Inactive' : 'Active' ?>"><button class="btn btn-outline-primary btn-sm"><?= $user['account_status'] === 'Active' ? 'Deactivate' : 'Activate' ?></button></form><form class="d-inline" method="post" action="../actions/admin.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete_user"><input type="hidden" name="id" value="<?= (int) $user['id'] ?>"><button class="btn btn-outline-danger btn-sm" data-confirm="Delete this user account? Submitted reports will remain with no linked account.">Delete</button></form></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="6" class="text-secondary">No registered users yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php admin_footer(); ?>
